def compress_consecutive_ranges(lst):
    if not lst:
        return []
    ranges = []
    i = 0
    n = len(lst)
    while i < n:
        j = i
        while j + 1 < n and lst[j + 1] == lst[j] + 1:
            j += 1
        ranges.append([lst[i], lst[j]])
        i = j + 1
    return ranges

def compress_runs_min_length(s, min_run):
    from itertools import groupby
    if not s:
        return ''
    parts = []
    for ch, group in groupby(s):
        run = list(group)
        length = len(run)
        if length >= min_run:
            parts.append(ch + str(length))
        else:
            parts.append(ch * length)
    return ''.join(parts)

def split_into_runs_by_sign(lst):
    def sign(x):
        if x > 0:
            return 1
        elif x < 0:
            return -1
        return 0
    if not lst:
        return []
    runs = []
    start = 0
    for i in range(1, len(lst) + 1):
        if i == len(lst) or sign(lst[i]) != sign(lst[start]):
            runs.append(lst[start:i])
            start = i
    return runs

