def subtract_business_days(start_day_num, n, weekend_days):
    def step(day, remaining):
        if remaining == 0:
            return day
        prev = day - 1
        if prev % 7 in weekend_days:
            return step(prev, remaining)
        return step(prev, remaining - 1)
    return step(start_day_num, n)

