def second_smallest_unique(nums):
    smallest = second = None
    for x in nums:
        if x == smallest or x == second:
            continue
        if smallest is None or x < smallest:
            second = smallest
            smallest = x
        elif second is None or x < second:
            second = x
    return second

def count_substring_occurrences_nonoverlapping(s, sub):
    if not sub:
        return 0
    count = 0
    i = 0
    step = len(sub)
    while i <= len(s) - step:
        if s[i:i + step] == sub:
            count += 1
            i += step
        else:
            i += 1
    return count

import heapq

def kth_smallest_abs_value(nums, k):
    def rank(x):
        magnitude = abs(x)
        return (magnitude, x)
    return heapq.nsmallest(k, nums, key=rank)[-1]
